def col0_row_of(b, k):
    # row at which the k-th most recent move (k=1 is the last) landed, if it was in column 0; else None
    if len(b.moves) < k or b.moves[-k] != 0:
        return None
    return sum(1 for m in b.moves[:len(b.moves) - k] if m == 0)

